from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/212.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'212-110',line,'4; 5.1','400-dpi full scan and all three enlarged bands. '+why,kind,count=count)
 if tree=='fr':
  r('puissance fibrée quadruple de $R$','puissance fibrée triple de $R$','opening continuation',kind='misprint of the original',why='The scan says quadruple, repeating the off-by-one error of p. 109. A degree-three nerve component consists of three composable arrows, so the corrected layer says triple; four counts vertices, not copies of the arrow object R.')
 r("pré-relation d'équivalence:","pré-relation d'équivalence :",'relation-to-groupoid paragraph',why='The printed colon is spaced.')
 r(r"(g',g\cdot a)(g,a)=(g'g,a),",r"(g',g\cdot a)(g,a)=(g'g,a)",'action composition display',why='There is no final comma in the displayed formula.')
 r('i.e.','i. e.','two abbreviations',count=2,why='The printed abbreviation is spaced.')
 r(r'si $a,b\in X$, alors',r'si $a,b\in X$ ; alors','transporter sentence',why='The print has a semicolon after X.')
 r('\\medskip\n\\noindent\\textbf{REMARQUE. ---}',r'\result{REMARQUE}{}','universe remark heading',why='The heading is ordinary roman, with period and short dash.')
 r('« Univers »',r'\fquote{Univers}','universe quotation',why='The scan has ordinary double quotation marks.')
 r(r"\fsection{5}{Quotient par une relation d'équivalence finie et plate}",r"\fsection{\normalfont 5}{\normalfont\uline{Quotient par une relation d'équivalence finie et plate}.}",'section 5 heading',why='The title is roman and straight-underlined, with its final period outside the underline. The existing section macro is preserved.')
 r(r'$R$ une pré-relation',r'$\mathcal R$ une pré-relation','Theorem 5.1, groupoid name',why='The whole groupoid has a distinct handwritten script R; its component R_1 has the ordinary typed R.')
 r('homomorphismes\n\\[\n  p_1^*,p_2^*:B\\rightrightarrows C\n\\]\n(= ensemble','homomorphismes $p_1^*,p_2^*:B\\rightrightarrows C$ (= ensemble','equalizer pair in Theorem 5.1',kind='structure',why='The pair of ring maps is inline inside the sentence, immediately followed by the parenthetical description.')
 r(r'p_1^*',r"p_1'",'first ring-map primes',count=3,why='Each ring map is marked by a prime, not an asterisk.')
 r(r'p_2^*',r"p_2'",'second ring-map primes',count=2,why='Each ring map is marked by a prime, not an asterisk.')
